def drive_api_stages(list_folders=gws_list_folders) -> dict[str, set[str]]:
    """{stage: folder names} under 00_Primary_Storage_Drive/01_PROJECTS, as Drive itself sees it.

    Four gws calls (~10 s). Raises RuntimeError (or OSError/TimeoutExpired from gws) when it
    cannot answer; the caller reports that instead of trusting the mount silently.
    """
    def one(q: str, what: str) -> str:
        hits = list_folders(q)
        if len(hits) != 1:
            raise RuntimeError(f"expected one {what} folder on Drive, found {len(hits)}")
        return hits[0]["id"]

    live = f"mimeType = '{FOLDER}' and trashed = false"
    # 'root' = top of My Drive: copies of this folder also sit inside backups (3 on 2026-10-31).
    root = one(f"name = '00_Primary_Storage_Drive' and 'root' in parents and {live}",
               "My Drive/00_Primary_Storage_Drive")
    projects = one(f"name = '01_PROJECTS' and '{root}' in parents and {live}", "01_PROJECTS")
    stage_ids = {f["id"]: f["name"] for f in list_folders(f"'{projects}' in parents and {live}")
                 if f["name"] in STAGE_DIRS}
    out: dict[str, set[str]] = {s: set() for s in STAGE_DIRS}
    if stage_ids:
        either = " or ".join(f"'{i}' in parents" for i in stage_ids)
        for f in list_folders(f"({either}) and {live}"):
            for p in f.get("parents", []):
                if p in stage_ids:
                    out[stage_ids[p]].add(f["name"])
    return out


def git_last_commit(path: Path) -> str:
    try:
        out = subprocess.run(["git", "-C", str(path), "log", "-1", "--format=%cs"],
                             capture_output=True, text=True, timeout=20)

def check(data: dict, dev_root: Path, drive_root: Path | None = None, *,
          since: _dt.date = MACHINE_CUTOFF, last_commit=git_last_commit,
          drive_api: dict[str, set[str]] | None = None, drive_api_error: str = "") -> dict:
    """drive_api: drive_api_stages() output, trusted over the mount for stage folders.
    drive_api_error: why the API could not answer; reported, and the mount is used instead."""
    rows = data.get("projects", [])
    problems: list[dict] = []

    def add(kind, name, detail=""):
        problems.append({"kind": kind, "name": name, "detail": detail})

    known_dev = {r.get("dev_folder") for r in rows if r.get("dev_folder")} | {r["name"] for r in rows}
    for d in sorted(p for p in dev_root.iterdir() if p.is_dir()):
        if d.name in SKIP or d.name.startswith("."):
            continue
        # Depth 2, the same limit KeystoneOS discovery uses: a group folder (Football/) or a
        # repo that holds repos (SpecialRequests/) has projects one level down.
        # Skipped: hidden folders, junctions/symlinks (LibraryProject/ZoteroInjestion points at
        # the real ZoteroInjestion on purpose), and anything inside a retired project.
        retired = {r.get("dev_folder") for r in rows if r.get("status") in RETIRED}
        # private_children: child repos are athlete-named, so they get no rows (portfolio.json
        # is pushed and published); the parent's own STATUS lists them instead.
        private = {r.get("dev_folder") for r in rows if r.get("private_children")}
        subs = [] if d.name in retired | private else sorted(
            c for c in d.iterdir()
            if c.is_dir() and not c.name.startswith(".") and not _is_link(c) and _is_repo(c))
        if d.name not in known_dev:
            add("unregistered_dev", d.name, _family_hint(d.name, rows))
        elif not _is_repo(d) and not subs:
            add("not_a_repo", d.name, "not on GitHub")
        for c in subs:
            rel = f"{d.name}/{c.name}"
            if rel not in known_dev:
                add("unregistered_dev", rel, _family_hint(c.name, rows))

    for r in rows:
        if r.get("status") in RETIRED:
            continue
        folder = r.get("dev_folder")
        if folder and not (dev_root / folder).is_dir():
            system = SYSTEM_REPOS.get(folder)
            if not (system and system.is_dir()):
                add("missing_dev", r["name"], folder)
        elif (folder and r.get("status") in ("active", "paused")    # finished work needs no Next
              and _is_repo(dev_root / folder) and _is_stub(dev_root / folder)):
            last = last_commit(dev_root / folder)
            try:
                touched = bool(last) and _dt.date.fromisoformat(last) > since
            except ValueError:
                touched = False
            if touched:
                add("stub_status", r["name"], f"worked on {last}, STATUS.md has no Next step")

    mount_ok = drive_root is not None and drive_root.is_dir()
    if drive_api_error:
        add("drive_api_unavailable", "", f"{drive_api_error}; used the Drive app's copy, which can be stale")
    if not mount_ok and drive_api is None:
        add("drive_unreachable", "", "Drive checks skipped")
    else:
        known_drive = {r.get("drive_folder") for r in rows if r.get("drive_folder")}
        for stage in STAGE_DIRS:
            if drive_api is not None:
                names = sorted(drive_api.get(stage, ()))
            else:
                base = drive_root / "01_PROJECTS" / stage
                names = sorted(p.name for p in base.iterdir() if p.is_dir()) if base.is_dir() else []
            for name in names:
                if f"01_PROJECTS/{stage}/{name}" not in known_drive:
                    add("unregistered_drive", f"{stage}/{name}", _family_hint(name, rows))
        unchecked = []
        for r in rows:
            folder = r.get("drive_folder")
            if not folder or r.get("status") in RETIRED:
                continue
            parts = folder.split("/")
            if drive_api is not None and len(parts) == 3 and parts[0] == "01_PROJECTS" and parts[1] in STAGE_DIRS:
                if parts[2] not in drive_api.get(parts[1], ()):
                    now = [s for s in STAGE_DIRS if parts[2] in drive_api.get(s, ())]
                    add("missing_drive", r["name"], folder + (f"; Drive has it in {now[0]}" if now else ""))
            elif not mount_ok:
                unchecked.append(r["name"])
            elif not (drive_root / folder).exists():
                add("missing_drive", r["name"], folder)
        if unchecked:   # API covers stage folders only; other paths need the mount
            add("drive_unreachable", "", f"{len(unchecked)} row(s) outside 01_PROJECTS/<stage> not checked")

    return {"status": "DRIFT" if problems else "OK", "problems": problems,
            "rows": len(rows), "drive_root": str(drive_root) if drive_root else None}

